const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.0/purchase_order_contracts/%7Bpurchase_order_contract_id%7D/subcontractor_schedule_of_values_status',
  headers: {'content-type': 'application/json'},
  body: {project_id: 34567, status: 'approved'},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/purchase_order_contracts/%7Bpurchase_order_contract_id%7D/subcontractor_schedule_of_values_status"),
    Content = new StringContent("{\"project_id\":34567,\"status\":\"approved\"}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
